<?php require_once __DIR__.'/../app/bootstrap.php'; require_once __DIR__.'/_auth.php'; if(empty($_SESSION['admin_ok'])){header('Location: /admin/login.php',true,303);exit;} if($_SERVER['REQUEST_METHOD']!=='POST'){?><?php auth_head('Logout'); auth_open('/admin/settings.php','Kembali ke Admin'); ?><section><div></div><div>Konfirmasi</div><h1>Keluar dari Admin?</h1><p>Sesi Anda akan diakhiri dan akses Administrator akan dikunci kembali.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button type="submit">YA, LOGOUT</button></form><a href="/admin/settings.php">BATAL</a></section><?php auth_close('Terima kasih telah mengelola website dengan baik.'); ?><?php exit;} check_csrf(); require_once __DIR__.'/../app/security.php';security_log('logout');$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',(bool)$p['secure'],(bool)$p['httponly']);}session_destroy();header('Location: /admin/login.php?logged_out=1',true,303);exit;